<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/custom/chinaplanetofficeexpenses/class/OfficeExpenseFinancialPlan.php';
$passed=0;$failed=0;
function pt(string $name,callable $f):void{global$passed,$failed;try{$f();$passed++;echo "PASS $name\n";}catch(Throwable$e){$failed++;echo "FAIL $name: ".$e->getMessage()."\n";}}
function pe($a,$b):void{if($a!==$b)throw new RuntimeException(var_export([$a,$b],true));}
function refuses(callable $f):void{try{$f();}catch(DomainException|InvalidArgumentException$e){return;}throw new RuntimeException('Expected refusal.');}
function source(string $kind,array $v=[]):array{return ['id'=>str_repeat('a',32),'office'=>'egypt','kind'=>$kind,'content'=>array_replace(['amount'=>'100.00','currency'=>'EGP','date'=>'2026-11-02','method'=>'cash'],$v)];}
function intent(array $row,array $values=[]):array{return OfficeExpenseFinancialPlan::intent($row,array_replace(['date'=>'2026-11-02','rate'=>'0.02','rate_date'=>'2026-11-02','rate_source'=>'SYNTHETIC approved rate','setup_revision'=>'2'],$values),'USD','2026-11-02');}
function plan(string $kind,array $v=[],array $i=[],?array $allocation=null):array{$r=source($kind,$v);return OfficeExpenseFinancialPlan::build($r,intent($r,$i),$allocation);}
pt('expense preserves original and explicit base valuation with a balanced cash credit',function(){ $p=plan('expense');pe($p['cash_amount'],'-100.00');pe($p['cash_base'],'-2.00');pe($p['lines'],[['role'=>'expense','debit'=>'2.00','credit'=>'0.00'],['role'=>'cash','debit'=>'0.00','credit'=>'2.00']]); });
pt('funding classification and customer identities cannot be guessed from free text',function(){refuses(fn()=>plan('deposit'));refuses(fn()=>plan('receipt'));pe(plan('deposit',[],['funding_type'=>'owner'])['lines'][1]['role'],'owner_funding');pe(plan('deposit',[],['funding_type'=>'transfer'])['lines'][1]['role'],'transfer_clearing');pe(plan('receipt',[],['party_id'=>'12'])['lines'][1]['role'],'customer_funds');pe(plan('receipt',[],['party_id'=>'12','invoice_id'=>'16'],['base_amount'=>'2.00','original_amount'=>'100.00'])['lines'][1]['role'],'customer_receivable');});
pt('foreign rates dates future posting and unexpected client identities fail closed',function(){refuses(fn()=>intent(source('expense'),['rate'=>'']));refuses(fn()=>intent(source('expense'),['date'=>'2026-11-03']));refuses(fn()=>intent(source('expense'),['rate_date'=>'2026-11-03']));refuses(fn()=>intent(source('expense'),['actor'=>'1']));refuses(fn()=>intent(source('expense'),['party_id'=>'1.0']));refuses(fn()=>intent(source('expense'),['rate'=>'0']));});
pt('USD identity valuation neither guesses FX nor accepts a nonidentity rate',function(){ $r=source('expense',['currency'=>'USD']);$i=intent($r,['rate'=>'1']);pe($i['valuation']['base_amount'],'100.00');pe($i['valuation']['rate'],'1.00000000');refuses(fn()=>intent($r,['rate'=>'0.9']));refuses(fn()=>intent($r,['rate'=>'bad']));});
pt('advance returns and expense settlement consume original carrying value and explicit FX',function(){ $a=['currency'=>'EGP','remaining_original'=>'100.00','remaining_base'=>'1.80'];$p=plan('advance_return',['amount'=>'50.00','settles_ref'=>str_repeat('b',32)],[],$a);pe($p['allocation_base'],'0.90');pe($p['lines'][2],['role'=>'fx_gain','debit'=>'0.00','credit'=>'0.10']);$s=plan('advance_settlement',['amount'=>'50.00','settles_ref'=>str_repeat('b',32)],[],$a);pe($s['cash_amount'],'0.00');pe($s['lines'][0]['role'],'expense');refuses(fn()=>plan('advance_return',['amount'=>'101.00'],[],$a));refuses(fn()=>plan('advance_return',[],[],null));});
pt('last original-currency repayment consumes all carrying-value rounding residue',function(){ $a=['currency'=>'EGP','remaining_original'=>'0.03','remaining_base'=>'0.01'];pe(OfficeExpenseFinancialPlan::carrying($a,'0.01'),'0.00');pe(OfficeExpenseFinancialPlan::carrying($a,'0.03'),'0.01');});
pt('payroll keeps gross expense net cash deductions and loan offsets distinct',function(){ $p=plan('payroll',['user_id'=>7,'gross'=>'8000.00','net'=>'3500.00','loan_repayment'=>'4000.00','deduction'=>'500.00'],['loan_ref'=>str_repeat('b',32)],['currency'=>'EGP','remaining_original'=>'4000.00','remaining_base'=>'80.00']);pe($p['cash_amount'],'-3500.00');pe($p['lines'][0],['role'=>'salary_expense','debit'=>'160.00','credit'=>'0.00']);pe($p['lines'][1]['credit'],'70.00');pe($p['lines'][2]['credit'],'10.00');pe($p['lines'][3]['credit'],'80.00');pe(count($p['lines']),4);});
pt('payroll repayment realizes a carrying-value difference rather than overwriting loan FX',function(){ $p=plan('payroll',['user_id'=>7,'gross'=>'8000.00','net'=>'4000.00','loan_repayment'=>'4000.00','deduction'=>'0.00'],['loan_ref'=>str_repeat('b',32)],['currency'=>'EGP','remaining_original'=>'4000.00','remaining_base'=>'90.00']);pe($p['lines'][3],['role'=>'fx_loss','debit'=>'10.00','credit'=>'0.00']);});
pt('component conversion residue is an explicit mapped rounding line',function(){ $p=plan('payroll',['user_id'=>7,'gross'=>'0.02','net'=>'0.01','loan_repayment'=>'0.00','deduction'=>'0.01'],['rate'=>'0.5']);pe($p['lines'][3],['role'=>'rounding','debit'=>'0.01','credit'=>'0.00']);});
pt('reversal exactly inverts recorded valuation without a new guessed exchange rate',function(){ $p=plan('expense');$r=OfficeExpenseFinancialPlan::reverse($p,'2026-11-02','2026-11-02');pe($r['cash_amount'],'100.00');pe($r['valuation'],$p['valuation']);pe($r['lines'][0]['credit'],'2.00');refuses(fn()=>OfficeExpenseFinancialPlan::reverse($p,'2026-10-31','2026-11-02'));});
echo "$passed passed, $failed failed\n";exit($failed?1:0);
